these template variables can be in the data (same level where the "label" is located) and must be prefixed with 'tpl_var'

If you submit data like this:

``` javascript
var data = {
    labels: ["January", "February", "March", "April", "May", "June", "July"],
    datasets: [
        {
            label: "My First dataset",
            fillColor: "rgba(220,220,220,0.2)",
            strokeColor: "rgba(220,220,220,1)",
            pointColor: "rgba(220,220,220,1)",
            pointStrokeColor: "#fff",
            pointHighlightFill: "#fff",
            pointHighlightStroke: "rgba(220,220,220,1)",
            data: [65, 59, 80, 81, 56, 55, 40],
            // introducing a new field usable in a template
            tpl_var_myVariable: 'this is a more detailed description of my first dataset'
        },
        {
            label: "My Second dataset",
            fillColor: "rgba(151,187,205,0.2)",
            strokeColor: "rgba(151,187,205,1)",
            pointColor: "rgba(151,187,205,1)",
            pointStrokeColor: "#fff",
            pointHighlightFill: "#fff",
            pointHighlightStroke: "rgba(151,187,205,1)",
            data: [28, 48, 40, 19, 86, 27, 90],
            // introducing a new field usable in a template
            tpl_var_myVariable: 'this is a test'
        }
    ]
};
```

you can could access the "tpl_var_myVariable" field in the e.g. tooltip template like this:

``` javascript
{
    // using the former introduced template variable in the tooltipTemplate
    tooltipTemplate: "<%if (tpl_var_myVariable){%><%=tpl_var_myVariable%>: <%}%><%= value %>",

    // using the former introduced template variable in the multiTooltipTemplate
    multiTooltipTemplate: "<%= tpl_var_myVariable%>"
}
```

This way you have more control of what is really shown in the legend and tooltips.

Once all code uses `helpers.template`, one can easily do the following when need arises (as described at https://github.com/nnnick/Chart.js/issues/281):

``` javascript
Chart.helpers.template = function(templateString, valuesObject) {
    if (templateString instanceof Function) {
        return templateString(valuesObject);
    }

    function tmpl(str, data) {
        return data.value;
    }
    return tmpl(templateString,valuesObject);
};
```

